H.background();
const W = H.W, Ht = H.H;
const cy = Ht * 0.56;
const cx0 = W * 0.5;
const Mach = Math.max(0, Math.min(0.85, P.vs));
const cpx = 120;
const vspx = Mach * cpx;
const period = 8.0;
const travel = (t % period) / period;
const startX = cx0 - 300, endX = cx0 + 300;
const sx = startX + (endX - startX) * travel;
const Te = 0.55;
const tEmitStart = t - 9 * Te;
for (let e = 0; e < 14; e++) {
  const te = tEmitStart + e * Te;
  if (te < 0) continue;
  const age = t - te;
  if (age <= 0) continue;
  const trav_e = ((te % period) / period);
  const ex = startX + (endX - startX) * trav_e;
  const r = cpx * age;
  if (r < 1 || r > 700) continue;
  const circ = [];
  for (let a = 0; a <= 48; a++) {
    const th = 2 * Math.PI * a / 48;
    circ.push([ex + r * Math.cos(th), cy + r * Math.sin(th)]);
  }
  H.path(circ, { color: H.colors.grid, width: 1.5 });
}
H.circle(sx, cy, 8, { fill: H.colors.warn });
H.arrow(sx, cy, sx + 46, cy, { color: H.colors.ink, width: 2 });
H.circle(endX + 40, cy, 7, { fill: H.colors.good });
H.text("ahead: higher f", endX - 60, cy - 22, { color: H.colors.good, size: 12 });
H.circle(startX - 40, cy, 7, { fill: H.colors.violet });
H.text("behind: lower f", startX - 30, cy - 22, { color: H.colors.violet, size: 12 });
const f0 = 500;
const fTow = f0 / (1 - Mach);
const fAway = f0 / (1 + Mach);
H.text("Doppler effect: f' = f0 * v / (v -/+ v_s)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
